(function(){
  'use strict';
  const T=window.Triage;
  let muted=true,timer=null,registration=null;
  const pending=()=>state.transactions.filter(T.needsReview).slice().reverse().sort((a,b)=>b.date.localeCompare(a.date));
  function permission(){return typeof Notification==='undefined'?'unsupported':Notification.permission;}
  async function register(){if(!('serviceWorker' in navigator)||!window.isSecureContext)return null;if(!registration)registration=await navigator.serviceWorker.register(new URL('notification-worker.js',location.href.split('#')[0]),{scope:new URL('./',location.href.split('#')[0]).pathname});return registration;}
  async function sendSystem(count){if(permission()!=='granted')return;try{const r=await register();if(!r)return;await navigator.serviceWorker.ready;await r.showNotification('Cashual · нужно уточнить категории',{body:count===1?'Появилась новая операция без определённой категории. Откройте Cashual и выберите категорию.':'Новых операций без категории: '+count+'. Откройте Cashual, чтобы распределить их.',tag:'cashual-categories',data:{url:new URL('./',location.href.split('#')[0]).href+'#review'}});}catch{toast('Системное уведомление недоступно. Операции ждут в «Нужно распределить».');}}
  function schedule(){if(muted)return;clearTimeout(timer);timer=setTimeout(collect,0);}
  function collect(){const result=T.scan(state.triage,state.transactions);state.triage=result.log;muted=true;persist();muted=false;decorate();if(result.newUnknown.length){toast('Нужно выбрать категорию для '+result.newUnknown.length+' новых операций');sendSystem(result.newUnknown.length);}}
  function decorate(){const count=pending().length,button=document.querySelector('[data-action="notifications"]');if(button){button.setAttribute('aria-label','Уведомления'+(count?': '+count+' операций без категории':''));const dot=button.querySelector('i');if(dot){dot.classList.toggle('triage-count',count>0);dot.textContent=count?String(count):'';}}const nav=document.querySelector('[data-page="review"]');if(nav)nav.setAttribute('title','Нужно распределить'+(count?' · '+count:''));}
  async function enable(){if(permission()==='unsupported'){toast('Этот браузер не поддерживает системные уведомления. Список операций доступен внутри Cashual.');return;}try{const result=await Notification.requestPermission();if(result==='granted'){await register();toast('Уведомления включены для новых неопределённых операций');}else toast(result==='denied'?'Уведомления заблокированы в браузере. Операции останутся в списке.':'Разрешение не выдано. Можно включить позже.');render();}catch{toast('Не удалось включить уведомления. Используйте список в приложении.');}}
  function review(){const rows=pending(),status=permission();return heading('Каждой операции — своё место.','Уточните категории, которые Cashual не смог определить.',`<button class="button ${status==='granted'?'secondary':'primary'}" data-enable-category-alerts ${status==='granted'?'disabled':''}>${status==='granted'?'✓ Уведомления включены':'♧ Включить уведомления'}</button>`)+`<div class="welcome-banner"><span class="sparkle">◇</span><span><strong>${rows.length?rows.length+' операций ждут категорию':'Всё распределено'}</strong>. ${rows.length?'После выбора категории операция исчезнет из этого списка.':'Новые неопределённые расходы и доходы появятся здесь автоматически.'}</span></div><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Нужно распределить</h2><p class="panel-subtitle">Переводы между своими счетами в список не попадают</p></div><span class="status-tag">${rows.length}</span></div><div class="review-list">${rows.map(t=>`<article class="review-row"><span class="review-type ${t.type}">${t.type==='income'?'↙':'↗'}</span><div class="review-info"><h3>${esc(t.merchant)}</h3><p>${dateLabel(t.date)} · ${t.type==='income'?'Доход':'Расход'} · ${accounts[t.account]?.name||'Наличные'}</p></div><strong class="sensitive ${t.type==='income'?'positive-text':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</strong><button class="button secondary" data-resolve-transaction="${esc(t.id)}">Выбрать категорию</button></article>`).join('')||'<div class="review-empty"><span>✓</span><h3>Всё по полочкам</h3><p>Неопределённых операций нет. Продолжайте свой финансовый день.</p></div>'}</div></section><div class="info-box section-gap"><strong>Как работают уведомления</strong><br>Cashual обнаруживает новые операции при ручном добавлении и импорте в открытом приложении. При разрешении браузера появится системное уведомление без сумм и названий продавцов; иначе — уведомление внутри приложения. Для обнаружения банковских списаний при закрытом Cashual нужна будущая серверная интеграция.<br>Разрешение браузера: ${status==='granted'?'включено':status==='denied'?'заблокировано — измените его в настройках сайта':status==='unsupported'?'не поддерживается':'ещё не запрошено'}. Выбор «Другое» или «Прочие доходы» вручную считается подтверждением, повторное уведомление не отправляется.</div>`;}
  function resolve(id){const t=state.transactions.find(t=>t.id===id);if(!t)return;const categories=t.type==='income'?F.incomeCategories:F.categories;openModal('Категория: '+t.merchant,`<div class="info-box">${t.type==='income'?'Поступление':'Расход'} ${money(t.amount)} · ${dateLabel(t.date)}</div>`+field('Куда отнести операцию?',`<select class="input" name="category">${options(categories,categories.includes(t.category)?t.category:undefined)}</select>`)+`<label class="review-rule"><input type="checkbox" name="remember" checked> Запомнить правило для этого продавца и типа операции</label>`,data=>{t.category=data.get('category');t.categoryConfirmed=true;if(data.get('remember')){const match=t.merchant.toLowerCase().trim();state.rules=state.rules.filter(r=>!(r.match===match&&(r.type||'expense')===t.type));state.rules.unshift({match,category:t.category,type:t.type});}toast('Категория сохранена');},'Подтвердить категорию');}
  const priorNotifications=actions.notifications;actions.notifications=()=>{const rows=pending();if(!rows.length)return priorNotifications();openModal('Есть операции без категории',`<div class="info-box"><strong>Нужно распределить: ${rows.length}</strong><br>Cashual не смог уверенно определить категорию расхода или дохода. Выберите её в списке операций.</div>`,()=>navigate('review'),'Распределить операции');};
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-enable-category-alerts'))enable();if(b.dataset.resolveTransaction)resolve(b.dataset.resolveTransaction);});
  document.addEventListener('change',event=>{if(event.target.name==='type'&&event.target.closest('#modal-form')){const select=document.querySelector('#modal-form select[name="category"]');if(!select)return;select.disabled=event.target.value==='transfer';select.innerHTML='<option value="auto">Определить по правилам</option>'+options(event.target.value==='income'?F.incomeCategories:F.categories);}});
  try{T.validate(state.triage);}catch{delete state.triage;}state.triage=T.scan(state.triage,state.transactions).log;
  window.CashualTriage={schedule,decorate,review};window.CashualGrowth.pages.review=review;navItems.splice(navItems.findIndex(x=>x[0]==='transactions')+1,0,['review','Нужно распределить','arrows']);if(location.hash==='#review')page='review';persist();muted=false;render();
})();
